import{_ as s,o as i,c as a,a5 as n}from"./chunks/framework.B6tQOu6W.js";const t="/assets/hello-world.BTHY9Inp.png",l="/assets/hello-world2.8NVSZjIr.png",r="/assets/ubuntu.cYJWKzfO.png",b=JSON.parse(`{"title":"Introduction à Docker","description":"Dans ce TP nous allons voir l'installation de Docker et les premiers exemples d'utilisations de votre nouvel environnement.","frontmatter":{"description":"Dans ce TP nous allons voir l'installation de Docker et les premiers exemples d'utilisations de votre nouvel environnement."},"headers":[],"relativePath":"tp/docker/introduction.md","filePath":"tp/docker/introduction.md","lastUpdated":1777924253000}`),o={name:"tp/docker/introduction.md"};function d(p,e,u,c,h,m){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction-a-docker" tabindex="-1">Introduction à Docker <a class="header-anchor" href="#introduction-a-docker" aria-label="Permalink to &quot;Introduction à Docker&quot;">​</a></h1><p>Dans ce TP nous allons voir l&#39;installation de Docker et les premiers exemples d&#39;utilisations de votre nouvel environnement.</p><details class="details custom-block"><summary>Sommaire</summary><nav class="table-of-contents"><ul><li><a href="#installation-de-docker-sous-windows">Installation de Docker sous Windows</a></li><li><a href="#lancer-docker">Lancer Docker</a></li><li><a href="#quota-et-utilisation">Quota et utilisation</a></li><li><a href="#premier-test">Premier test</a></li><li><a href="#second-test">Second test</a></li><li><a href="#les-sources-de-l-image-hello-world">Les sources de l&#39;image hello world</a></li><li><a href="#pour-aller-plus-loin">Pour aller plus loin</a><ul><li><a href="#creer-un-fichier-dans-la-machine">Créer un fichier dans la machine</a></li><li><a href="#avoir-acces-aux-fichiers-de-votre-machine">Avoir accès aux fichiers de votre machine</a></li></ul></li><li><a href="#utiliser-docker-pour-developper">Utiliser Docker pour développer</a><ul><li><a href="#yt-dlp">yt-dlp</a></li><li><a href="#autres-exemples">Autres exemples</a></li></ul></li><li><a href="#nettoyage">Nettoyage</a></li><li><a href="#allons-plus-loin">Allons plus loin</a></li></ul></nav></details><h2 id="installation-de-docker-sous-windows" tabindex="-1">Installation de Docker sous Windows <a class="header-anchor" href="#installation-de-docker-sous-windows" aria-label="Permalink to &quot;Installation de Docker sous Windows&quot;">​</a></h2><p>Pour installer Docker rien de plus simple, il suffit d&#39;utiliser l&#39;installeur officiel en le téléchargeant sur <a href="https://docs.docker.com/desktop/install/windows-install/" target="_blank" rel="noreferrer">le site de Docker.</a></p><h2 id="lancer-docker" tabindex="-1">Lancer Docker <a class="header-anchor" href="#lancer-docker" aria-label="Permalink to &quot;Lancer Docker&quot;">​</a></h2><p>Lancez Docker Desktop. Au premier démarrage, Docker vous demandera peut-être d&#39;activer WSL2 (Windows Subsystem for Linux 2) — acceptez, c&#39;est le backend recommandé.</p><h2 id="quota-et-utilisation" tabindex="-1">Quota et utilisation <a class="header-anchor" href="#quota-et-utilisation" aria-label="Permalink to &quot;Quota et utilisation&quot;">​</a></h2><p>Dans nos différents tests, nous allons utiliser le registry Docker officiel. Celui-ci a mis en place des quotas assez restrictifs pour les utilisateurs non authentifiés. Il est donc préférable de créer un compte Docker et de vous authentifier sur le registry. Pour cela, rien de plus simple, il suffit d&#39;entrer la commande suivante dans une console :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Il vous sera demandé de vous authentifier avec votre compte Docker. Une fois authentifié, vous pourrez télécharger des images avec une limite beaucoup plus élevée.</p><h2 id="premier-test" tabindex="-1">Premier test <a class="header-anchor" href="#premier-test" aria-label="Permalink to &quot;Premier test&quot;">​</a></h2><p>Maintenant qu&#39;il est installé sur votre poste, rien de plus simple. Dans une console, entrez la commande suivante :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Vous devez voir la version de Docker.</p><ul><li>Que constatez-vous ?</li><li>Pourquoi est-ce important d&#39;utiliser une version récente ?</li></ul><h2 id="second-test" tabindex="-1">Second test <a class="header-anchor" href="#second-test" aria-label="Permalink to &quot;Second test&quot;">​</a></h2><p>Maintenant que nous savons que Docker est correctement installé, testons avec une « machine » fournie par Docker. L&#39;image se nomme <code>hello-world</code>, celle-ci ne fait qu&#39;afficher un message de bienvenue. De nouveau, dans la console, entrez la commande suivante :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello-world</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+t+'" alt="Docker Hello World" loading="lazy"></p><ul><li>Que constatez-vous ?</li><li>Comment être certain que l&#39;image n&#39;a rien fait d&#39;anormal sur notre machine ?</li></ul><h2 id="les-sources-de-l-image-hello-world" tabindex="-1">Les sources de l&#39;image hello world <a class="header-anchor" href="#les-sources-de-l-image-hello-world" aria-label="Permalink to &quot;Les sources de l&#39;image hello world&quot;">​</a></h2><p>Maintenant que nous avons lancé notre première « vraie » machine, intéressons-nous à son fonctionnement. Vous avez dû constater le terme « Pulling From » : c&#39;est l&#39;image (ou les morceaux d&#39;image) utile au fonctionnement de votre service. Celle-ci est téléchargée directement depuis le « Docker Hub » (il est également possible d&#39;avoir un Hub privé). Vous pouvez voir « les sources » de l&#39;image en question : <a href="https://github.com/docker-library/hello-world" target="_blank" rel="noreferrer">ici</a>. Comme beaucoup de projets libres, l&#39;image est disponible sur Github.</p><p>Surprise ! On retrouve des plateformes (amd64, i686, armXX). Et c&#39;est normal, Docker est multiplateforme. Dans le cas de notre exemple, l&#39;exécutable « hello » est codé en C, il est donc logique de retrouver l&#39;exécutable pour les différentes plateformes où l&#39;image doit fonctionner.</p><p>Maintenant que nous avons vu le projet, entrons plus en détail, allons voir la définition de notre image : le <a href="https://github.com/docker-library/hello-world/blob/master/i386/hello-world/Dockerfile" target="_blank" rel="noreferrer">fichier Dockerfile.</a></p><p><img src="'+l+'" alt="Hello World 2" loading="lazy"></p><p>Peu d&#39;informations, 3 lignes :</p><ul><li><code>FROM scratch</code> (Image de base, celle utilisée comme référence — elle aussi possède un Dockerfile).</li><li><code>COPY hello /</code> (ajoute le fichier hello à la racine de votre « machine »).</li><li><code>CMD [&quot;/hello&quot;]</code> (Commande lancée au démarrage de votre image).</li></ul><p>PS : On créera un Dockerfile dans le 2nd TP.</p><h2 id="pour-aller-plus-loin" tabindex="-1">Pour aller plus loin <a class="header-anchor" href="#pour-aller-plus-loin" aria-label="Permalink to &quot;Pour aller plus loin&quot;">​</a></h2><p>Bon, un texte à l&#39;écran c&#39;est bien… Mais si on lançait un système entier ? Ubuntu par exemple. Pour ça rien de plus simple, dans la console lancez :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+r+'" alt="Ubuntu" loading="lazy"></p><p>Et voilà, vous avez un Linux complètement opérationnel en quelques minutes sur votre poste Windows. Pratique ! Même si ce n&#39;est pas vraiment le but premier de Docker, c&#39;est sympa.</p><blockquote><p>⚠️ L&#39;image Ubuntu dans Docker est volontairement minimaliste : elle ne contient pas <code>sudo</code>, peu d&#39;outils préinstallés, et certaines commandes habituelles peuvent manquer. C&#39;est tout à fait normal.</p></blockquote><p>Utilisez un peu le shell de votre « nouveau Linux », exemples de commandes :</p><ul><li><code>uname -a</code> : Affiche la version du noyau.</li><li><code>whoami</code> : Qui suis-je ? (normalement root — d&#39;ailleurs, est-ce normal ?).</li><li><code>top</code> : Affiche les processus en cours.</li><li><code>ls /</code></li></ul><p>Questions :</p><ul><li>D&#39;ailleurs, pourquoi <code>top</code> ne retourne-t-il que deux processus ?</li><li>Aucune trace des fichiers de votre machine… normale, de base rien n&#39;est accessible.</li></ul><h3 id="creer-un-fichier-dans-la-machine" tabindex="-1">Créer un fichier dans la machine <a class="header-anchor" href="#creer-un-fichier-dans-la-machine" aria-label="Permalink to &quot;Créer un fichier dans la machine&quot;">​</a></h3><p>Créez un fichier vide avec la commande :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">touch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fichier_test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Vérifiez avec un <code>ls</code> que le fichier est bien présent. Vous pouvez quitter l&#39;image en saisissant <code>exit</code> dans le terminal. Relancez de nouveau l&#39;image avec la commande :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Faites à nouveau un <code>ls</code>, que constatez-vous ? Et bien oui, le fichier n&#39;est plus présent… C&#39;est normal, tous les fichiers créés dans l&#39;image sont non persistants (c&#39;est-à-dire qu&#39;ils sont supprimés à chaque fois que l&#39;image s&#39;arrête).</p><h3 id="avoir-acces-aux-fichiers-de-votre-machine" tabindex="-1">Avoir accès aux fichiers de votre machine <a class="header-anchor" href="#avoir-acces-aux-fichiers-de-votre-machine" aria-label="Permalink to &quot;Avoir accès aux fichiers de votre machine&quot;">​</a></h3><p>Bon, c&#39;est bien, mais si l&#39;on donnait accès à un stockage persistant à notre image. Sur votre machine le stockage persistant c&#39;est votre disque dur (HDD, SSD, etc.). Avec Docker (comme sous Linux d&#39;ailleurs) on parle de « monter un volume » : une fois monté, ce volume sera accessible comme un dossier (ou un fichier, on y reviendra).</p><h4 id="monter-un-dossier" tabindex="-1">Monter un dossier <a class="header-anchor" href="#monter-un-dossier" aria-label="Permalink to &quot;Monter un dossier&quot;">​</a></h4><p>Pour monter un volume, il suffit d&#39;ajouter un <code>-v</code> à la commande de lancement.</p><p>⚠️⚠️ Attention ! L&#39;accès est en lecture ET en écriture sur <strong>VOTRE MACHINE</strong>, donc soyez prudent.</p><p>Sous Windows (PowerShell) :</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">${PWD}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/mnt/&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">it ubuntu bash </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Monte le dossier courant dans le /mnt du Docker.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Sous Unix / macOS :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:/mnt/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Monte le dossier courant dans le /mnt du Docker.</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Lancez la commande, <code>ls /mnt</code> vous devriez voir vos fichiers.</p><h4 id="monter-un-fichier" tabindex="-1">Monter un fichier <a class="header-anchor" href="#monter-un-fichier" aria-label="Permalink to &quot;Monter un fichier&quot;">​</a></h4><p>Comme je le disais dans l&#39;introduction, avec Docker il est possible de rendre accessible un dossier, mais également un fichier. Pour les fichiers la commande est la même, sauf qu&#39;au lieu de spécifier un dossier on spécifie le chemin d&#39;un fichier. Exemple :</p><p>Windows (PowerShell) :</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">${PWD}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/mon_fichier:/mnt/mon_fichier&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">it ubuntu bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Unix / macOS :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/mon_fichier:/mnt/mon_fichier</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Le fichier est maintenant accessible dans votre image Docker. Il est également possible de limiter l&#39;accès à votre fichier en le montant en « RO » (lecture seule) :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">pwd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/mon_fichier:/mnt/mon_fichier:ro</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ubuntu</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Et c&#39;est là que l&#39;on voit la puissance : on verra qu&#39;il sera possible par la suite de créer de vraies « stacks » applicatives qui définiront l&#39;ensemble des paramètres de notre environnement (cloisonné) en gérant finement les droits d&#39;accès à la configuration. Un régal !</p><h2 id="utiliser-docker-pour-developper" tabindex="-1">Utiliser Docker pour développer <a class="header-anchor" href="#utiliser-docker-pour-developper" aria-label="Permalink to &quot;Utiliser Docker pour développer&quot;">​</a></h2><p>Docker est un outil intéressant pour développer : il permet de créer des environnements de développement isolés et facilement reproductibles. Vous pouvez avec Docker packager une application avec toutes ses dépendances pour la faire fonctionner sur n&#39;importe quel système d&#39;exploitation. Pour vous donner envie d&#39;utiliser Docker, nous allons tester des exemples atypiques.</p><h3 id="yt-dlp" tabindex="-1">yt-dlp <a class="header-anchor" href="#yt-dlp" aria-label="Permalink to &quot;yt-dlp&quot;">​</a></h3><p>yt-dlp est un outil en ligne de commande permettant de télécharger des vidéos sur YouTube et d&#39;autres sites de streaming. Il est disponible sous forme de conteneur Docker, ce qui vous permet de l&#39;utiliser sans avoir à l&#39;installer sur votre système.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ytdl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;docker run --rm -v &quot;$(pwd):/downloads&quot; -it jauderho/yt-dlp:latest -x --audio-format mp3 --audio-quality 0 --embed-metadata&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Qu&#39;avons-nous ici ?</p><ul><li><code>alias ytdl=</code> : Crée un alias pour la commande, ce qui vous permet de l&#39;utiliser plus facilement. (C&#39;est une commande shell, pas une commande Docker).</li><li><code>docker run</code> : Lance un conteneur Docker.</li><li><code>--rm</code> : Supprime le conteneur après son utilisation.</li><li><code>-v &quot;$(pwd):/downloads&quot;</code> : Monte le répertoire courant dans le conteneur à l&#39;emplacement <code>/downloads</code>. Cela vous permet de télécharger des fichiers directement dans votre répertoire de travail.</li><li><code>-it</code> : Lance le conteneur en mode interactif.</li><li><code>jauderho/yt-dlp:latest</code> : Spécifie l&#39;image Docker à utiliser. Dans ce cas, il s&#39;agit de l&#39;image <code>jauderho/yt-dlp</code> avec la dernière version.</li><li><code>-x --audio-format mp3 --audio-quality 0 --embed-metadata</code> : Ce sont les options passées à <code>yt-dlp</code>. Ces options permettent de télécharger l&#39;audio au format MP3 avec la meilleure qualité et d&#39;incorporer les métadonnées.</li></ul><p>Si vous souhaitez télécharger une vidéo pour en sauvegarder une copie au format MP3, il vous suffit de lancer la commande suivante :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ytdl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://www.youtube.com/watch?v=dQw4w9WgXcQ</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Je vous laisse tester. Vous allez voir que le téléchargement est rapide et que la qualité est au rendez-vous. Vous pouvez également utiliser d&#39;autres options de <code>yt-dlp</code> pour personnaliser le téléchargement selon vos besoins.</p><h3 id="autres-exemples" tabindex="-1">Autres exemples <a class="header-anchor" href="#autres-exemples" aria-label="Permalink to &quot;Autres exemples&quot;">​</a></h3><p>Autre exemple « amusant » : SpotDL, un outil permettant de télécharger des chansons depuis Spotify. Il est également disponible sous forme de conteneur Docker.</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">alias</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spotdl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;docker run --rm -v &quot;$(pwd):/music&quot; spotdl/spotify-downloader --audio {youtube,youtube-music,soundcloud,piped} --output &quot;{artist}/{album}/{track-number} - {title}.{output-ext}&quot; download&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Qu&#39;avons-nous ici ?</p><ul><li><code>alias spotdl=</code> : Crée un alias pour la commande, ce qui vous permet de l&#39;utiliser plus facilement. (C&#39;est une commande shell, pas une commande Docker).</li><li><code>docker run</code> : Lance un conteneur Docker.</li><li><code>--rm</code> : Supprime le conteneur après son utilisation.</li><li><code>-v &quot;$(pwd):/music&quot;</code> : Monte le répertoire courant dans le conteneur à l&#39;emplacement <code>/music</code>. Cela vous permet de télécharger des fichiers directement dans votre répertoire de travail.</li><li><code>spotdl/spotify-downloader</code> : Spécifie l&#39;image Docker à utiliser.</li><li><code>--audio {youtube,youtube-music,soundcloud,piped}</code> : Indique les sources audio à utiliser pour le téléchargement.</li><li><code>--output &quot;{artist}/{album}/{track-number} - {title}.{output-ext}&quot;</code> : Spécifie le format de sortie pour les fichiers téléchargés.</li><li><code>download</code> : Indique que vous souhaitez télécharger une chanson.</li></ul><p>Si vous souhaitez télécharger une chanson, il vous suffit de lancer la commande suivante :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">spotdl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://open.spotify.com/intl-fr/track/4PTG3Z6ehGkBFwjybzWkR8?si=b667ca05a91e4558</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>L&#39;outil SpotDL va rechercher dans les métadonnées de la chanson pour la retrouver sur YouTube et la télécharger.</p><h2 id="nettoyage" tabindex="-1">Nettoyage <a class="header-anchor" href="#nettoyage" aria-label="Permalink to &quot;Nettoyage&quot;">​</a></h2><p>À la fin du TP, vous avez probablement plusieurs images et conteneurs qui traînent sur votre machine. Voici comment faire le ménage :</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Liste tous les conteneurs (y compris arrêtés)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> images</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # Liste toutes les images téléchargées</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prune</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Supprime les conteneurs arrêtés, images inutilisées et cache</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>⚠️ <code>docker system prune</code> est irreversible. Vérifiez ce que vous supprimez avant de confirmer.</p></blockquote><h2 id="allons-plus-loin" tabindex="-1">Allons plus loin <a class="header-anchor" href="#allons-plus-loin" aria-label="Permalink to &quot;Allons plus loin&quot;">​</a></h2><p>Nous avons ici des petites machines pour jouer… C&#39;est rigolo… Mais Docker est bien plus puissant que ça. <a href="./creer_server_local.html">La suite c&#39;est par ici</a></p>',88)])])}const v=s(o,[["render",d]]);export{b as __pageData,v as default};
